('NW001', '01-legacy-plc-bus', 'X10 (X-10 Powerline Carrier / 电力载波)', array['x10', 'x-10', 'powerhouse', 'plug n power', 'bsr x10', 'plc carrier', 'x10 pro']::text[], 'Pico Electronics (Scotland, 1975) 创立协议；北美经 X10 Wireless Technology / Authinx / RadioShack Plug ''n Power 等渠道长期零售；现以第三方存量模组与二手市场为主。', '1975 · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '120V AC 电力线载波：约 120 kHz 过零点附近短脉冲突发，典型有效吞吐约 20 bps；House Code (A–P) + Unit Code (1–16)；多为单向或弱双向；分相供电需相间耦合器（phase coupler）。拓扑为总线共享电力线，抗噪能力弱。', array['免拉控制线、改造成本极低', '模组与知识库存量极大，DIY 友好', '可与部分 Insteon 双模设备共存过渡']::text[], array['电机/变频器/开关电源噪声易导致丢包', '速率极低、场景联动脆弱', 'Indigo 等平台已标 Legacy、厂商测试停滞']::text[], array['X10 墙开/调光器', 'Appliance Module', 'CM11A/CM15A PC 接口', 'Phase Coupler', 'RF 遥控器 + RR501']::text[], array['1970–1990s 北美老宅存量', '极低预算 DIY 过渡', '临时照明遥控']::text[], '公开电商二手/清仓模组约 USD $8–$40/件；整屋 DIY 包常见 <$300。无强制订阅。口径：Amazon/论坛公开价，fetched_on 2026-10-24。', '存量接手：优先盘点相间耦合与噪声源；长期建议整体替换。桥接：可用 Insteon 双模作短期共存，最终迁移至 Lutron HomeWorks / Caséta 或 Control4 Zigbee/EA 灯光；不建议保留 X10 作为豪宅主控。电力线可保留，控制层推倒重来。', '对四巨头：无官方一级驱动价值；仅作识别词条。迁移目标通常为 Lutron 或 C4 无线/有线灯光。', 'E2'::evidence_tier, '[{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"HomeToys lighting tech overview","fetchedOn":"2026-10-24"},{"url":"https://forums.indigodomo.com/viewtopic.php?p=231266","note":"Indigo Domotics X10 legacy policy 2026","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW002', '01-legacy-plc-bus', 'UPB (Universal Powerline Bus)', array['upb', 'universal powerline bus', 'pcs upb', 'pulseworx', 'simply automated upb']::text[], '协议由 Powerline Control Systems (PCS) 于 1999 年前后研发；Simply Automated、HAI/Leviton、PulseWorx 等采用。现为存量小众协议，配件依赖专项渠道。', '1999 · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '电力线脉冲位置调制 (PPM)，峰值脉冲约 40V 量级（远强于 X10 的约 4V 载波），双向确认；低频脉冲可经变压器跨相传播，抗噪显著优于 X10；地址空间更大。', array['比 X10 可靠一个数量级', '双向确认适合灯光状态反馈', '老宅免重新拉低压控制线']::text[], array['生态停滞、新房几乎不选', '编程软件与工程师稀缺', '与现代 Matter/Thread 无原生互通']::text[], array['PCS/Simply Automated 墙开与调光', 'PulseWorx 模组', 'UPStart 配置软件', '相间耦合器（较少需要）']::text[], array['2000s 定制宅存量', 'HAI Omni 灯光联动遗产', '对可靠性有要求的 PLC 改造']::text[], '存量模组公开渠道约 USD $40–$120/路；整屋视规模 $1.5k–$6k 硬件（不含人工）。无订阅。E3/E4 电商与论坛口径 2026-10-24。', '接手建议：若灯光稳定可短期保留，经串口/IP 网关挂到 Elk 或旧 HAI；中长期用 Lutron RadioRA 3 / HomeWorks 或 C4 灯光替换墙开。电力线本身无需改，换装墙开即可。', 'C4/Crestron/Savant 历史上有 UPB 驱动案例，但新项目不推荐；Lutron 无 UPB 原生。', 'E2'::evidence_tier, '[{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"UPB vs X10 technical comparison","fetchedOn":"2026-10-24"},{"url":"https://cocoontech.com/","note":"CocoonTech UPB/HAI community","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW003', '01-legacy-plc-bus', 'Simply Automated (UPB Modules)', array['simply automated', 'sa upb', 'simply automated dimmer', 'upb switch']::text[], 'Simply Automated — 北美 UPB 硬件主力之一，与 PCS 协议生态绑定；面向定制安装与 DIY 存量。', '约 2000s · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '基于 UPB PPM 电力线双向通信；墙开/调光器本地场景与网络组地址。', array['硬件质量口碑优于廉价 X10', '支持本地场景不依赖云', '可与 HAI/Elk 联动']::text[], array['采购渠道变窄', '无手机原生体验', '未来零配件风险']::text[], array['UPB 调光开关', 'Appliance 控制器', 'USB/串口接口', 'Scene 控制器']::text[], array['存量 UPB 住宅维护', '小规模灯光自动化']::text[], '公开零售约 USD $50–$150/开关。无订阅。', '作为 UPB 执行层识别；替换路径同 NW002，优先保留线缆与配电拓扑，换现代墙控。', '挂到四巨头仅作过渡驱动；新装不选。', 'E3'::evidence_tier, '[{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"Simply Automated / UPB mention","fetchedOn":"2026-10-24"},{"url":"https://cocoontech.com/","note":"Forum discussions","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW004', '01-legacy-plc-bus', 'Insteon (Dual-Band Powerline + RF Mesh)', array['insteon', 'smartlabs', 'smarthome insteon', 'insteon hub', 'dual-band mesh']::text[], 'SmartLabs / SmartHome 于 2005 年前后推出；2022 年云服务一度中断后由新团队接盘，官网与 Hub 2 / Director App 仍在售。', '2005 · ACTIVE_NICHE', 'ACTIVE_NICHE', '双模网格：电力线 Insteon PLC + 约 915 MHz RF；设备互为中继；早期兼容监听/发送 X10；Hub 提供 IP/App/语音桥。', array['双模改善纯 PLC 死角', '设备可无云本地联动', '北美零售渠道仍可见']::text[], array['2022 停服阴影未消、信任受损', 'Hub 订阅与生态规模受限', '非 CEDIA 豪宅主流']::text[], array['Insteon Hub 2', '墙开/调光/KeypadLinc', '插拔模组', '门窗/运动传感', 'Mini Remote']::text[], array['DIY 中产住宅', '从 X10 升级的存量用户', '局部灯光自动化']::text[], 'Hub 与开关公开价约 Hub $100–$150、开关 $40–$80；App 订阅以官网为准。fetched_on 2026-10-24。', '对话框识别后说明属 DIY 双模非四巨头级；大宅建议迁移 Lutron/C4。局部可作边缘灯控，串口/IP 桥较少用于专业机柜。', '非四巨头主路径；或作临时边缘，最终替换。', 'E1'::evidence_tier, '[{"url":"https://www.insteon.com/","note":"Official Insteon site","fetchedOn":"2026-10-24"},{"url":"https://www.insteon.com/pages/why-insteon","note":"Dual-mesh technology page","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW005', '01-legacy-plc-bus', 'Leviton HAI OmniPro II / Omni Controllers', array['hai', 'omnipro', 'omnipro ii', 'leviton hai', 'home automation inc', 'omni iie', 'lumina']::text[], 'Home Automation, Inc. (HAI) 被 Leviton 收购；Omni / OmniPro II / Lumina 系列为经典有线安防+自动化主机，现以存量维护为主，配件稀缺。', '约 1985（HAI）· 被 Leviton 收购后逐步 LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '专有总线 + 传统有线防区；串口/以太网扩展；常联动 UPB/X10/串口灯光；RS-232/IP 对第三方开放程度较高（CocoonTech 时代热门）。', array['安防与自动化一体、工程师熟悉度高', '串口生态丰富可桥四巨头', '硬线防区可靠']::text[], array['官方新机近停、备件难', 'UI/App 体验过时', '扩展依赖二手']::text[], array['OmniPro II 主机', 'OmniTouch 面板', '有线防区扩展', '串口灯光接口', 'Lumina 系列']::text[], array['1995–2015 定制宅地下室主机柜', '安防优先型住宅存量']::text[], '二手主机公开市场差异大约 USD $200–$800；监控若仍接中央站另计月费。E3 口径。', '接手：保留硬线门磁/红外，主机可迁 Elk M1 或经 EnvisaLink/Konnected 智能化；灯光侧拆 UPB 改 Lutron。向 C4/Crestron 用串口/IP 驱动过渡后整体替换控制层。', '历史上 C4/Crestron 有 HAI 驱动；新项目改 Elk 或 ADC 面板 + 四巨头。', 'E2'::evidence_tier, '[{"url":"https://cocoontech.com/threads/centralite-litejet-and-omnipro-ii.24099/","note":"CocoonTech OmniPro/LiteJet","fetchedOn":"2026-10-24"},{"url":"https://www.leviton.com/","note":"Leviton corporate (HAI heritage)","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW006', '01-legacy-plc-bus', 'Leviton GreenMAX DRC (Wired Lighting Control)', array['greenmax', 'greenmax drc', 'leviton greenmax', 'drc lighting', 'leviton wired dimming']::text[], 'Leviton 商业/高定有线调光与房间控制平台 GreenMAX DRC，面向节能法规与集中调光机柜。', '2010s · ACTIVE_NICHE', 'ACTIVE_NICHE', '有线调光柜 + 数字房间控制器；支持 0-10V/相位/继电器负载；网络化配置；偏商业但下放到大宅机电房。', array['满足商业节能与集中柜需求', '与 Leviton 配电/传感器体系协同', '比纯无线更适合大负载']::text[], array['住宅 CEDIA 渠道声量弱于 Lutron/Vantage', '面板设计语言偏商用', '与四巨头灯光哲学不同']::text[], array['GreenMAX 调光柜', 'DRC 房间控制器', 'Occupancy/Daylight 传感', '网络网关']::text[], array['大型别墅机电房', '商住混合、会所、多套房灯光']::text[], '工程报价通常按回路，典型项目数万美元级；公开零售少。E3。', '若已装 GreenMAX：可保留柜体作执行层，四巨头经干接点/0-10V/网关做上层场景；或评估改 HomeWorks 柜。', '常作执行层挂 C4/Crestron；豪宅面板体验仍推 Lutron/Vantage/Savant。', 'E2'::evidence_tier, '[{"url":"https://www.leviton.com/","note":"Leviton GreenMAX product family","fetchedOn":"2026-10-24"},{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"Lighting marketplace context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW007', '01-legacy-plc-bus', 'Leviton Structured Media Center (SMC / 结构化布线箱)', array['structured media', 'leviton smc', 'structured wiring enclosure', 'leviton media panel']::text[], 'Leviton 结构化媒体箱（Structured Media Enclosure）——弱电星型铜缆/光纤汇聚箱，非逻辑控制器但为北美有线智能宅基础设施。', '1990s · ACTIVE_MAIN', 'ACTIVE_MAIN', '星型 Cat5e/6/6A、同轴、光纤汇聚；无专有控制协议；为安防/网络/音视频/门禁提供物理层机柜。', array['北美新建标配弱电箱形态', '配件丰富易扩容', '与品牌无关可混用']::text[], array['本身无智能逻辑', '劣质端接导致后期全屋故障', '常被误认为‘智能主机’']::text[], array['SMC 箱体多尺寸', '语音/数据模块', '视频分配', '光纤盘', '风扇/电源配件']::text[], array['新建与翻新弱电星型布线', '机柜整理与四巨头机架上联']::text[], '箱体公开 HD/Lowes 约 USD $40–$200；满配模块另计。无订阅。', '问诊时区分‘有 SMC 箱≠有智能系统’。保留星型线可直接服务 C4/Crestron/Savant/Lutron 与安防 PoE。', '四巨头机柜上联的物理前提；非竞争品牌。', 'E1'::evidence_tier, '[{"url":"https://www.leviton.com/","note":"Leviton SMC product pages","fetchedOn":"2026-10-24"},{"url":"https://www.homedepot.com/","note":"Public retail structured media enclosures","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW008', '01-legacy-plc-bus', 'LiteTouch (LiteTouch 2000 / 5000LC)', array['litetouch', 'lite touch', 'litetouch 2000', 'litetouch 5000', '5000lc']::text[], '北美初代豪宅低压面板调光系统（约 1970s 末起）；后经 Nortek 等流转，2015 年 Savant 宣布停产停支持；Touch-Plate 等提供保留原低压线升级方案。', '约 1978 · DISCONTINUED', 'DISCONTINUED', '低压星型/总线面板 + 集中调光柜；按键低电压信号回柜控制市电回路。柜内相位/变压器负载常见于 80–2000s 大宅。', array['星型低压线是可复用资产', '面板化场景在当时代领先', '升级套件可避免重新开墙拉线']::text[], array['2015 后无官方备件', '面板与柜不兼容混用他牌', '找原厂技师成本高']::text[], array['LiteTouch 2000/5000LC 主机柜', '低压按键面板', '调光模块', '电源/扩展']::text[], array['80–2010 北美豪宅继承房', '设计师面板化灯光遗产']::text[], '整屋升级报价因规模差异大，常见数千至数万美元（含面板替换）；Touch-Plate RFQ 定制。E2/E3。', '强烈建议：保留低压线缆，整系统替换为 Touch-Plate / Lutron HomeWorks / Savant 灯光执行层；不可局部混用。Savant 收购遗产但官方已停支持。', '优先 Savant 或 Lutron 路径复用低压线；C4 需评估驱动与柜体改造。', 'E2'::evidence_tier, '[{"url":"https://touchplate.com/wp-content/uploads/product-documents/Support/Upgrading-LiteTouch-FAQs.pdf","note":"Touch-Plate LiteTouch upgrade FAQ","fetchedOn":"2026-10-24"},{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"Legacy lighting context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW009', '01-legacy-plc-bus', 'Vantage Controls InFusion (Legrand)', array['vantage', 'vantage controls', 'infusion', 'vantage station bus', 'legrand vantage', 'squaretouch']::text[], 'Vantage Controls — 高定有线灯光与场景品牌，现属 Legrand；InFusion 控制器 + Station Bus 两线低压拓扑；西岸设计师渠道强。', '1980s · ACTIVE_NICHE', 'ACTIVE_NICHE', 'Station Bus 两线制低压总线连接金属/玻璃按键站；InFusion 控制器处理场景与负载柜；可混合无线扩展；编程属专业经销商闭源体系。', array['面板质感与建筑一体化顶尖', '两线拓扑布线优雅', '设计师/建筑师认知度高']::text[], array['造价高、经销商锁定', '部分旧款 SquareTouch/FineTouch 已停产', '与四巨头重叠时需明确主控边界']::text[], array['InFusion 控制器', 'Station Bus 按键站', '调光/继电器柜', 'Equinox 面板', '传感器']::text[], array['当代建筑高定住宅', '西海岸/山地度假宅', '灯光为主的全屋场景']::text[], '按键站公开工程价常数百美元级/站，整屋灯光常 $20k–$100k+。无消费级订阅。E3。', '可作为豪宅灯光主系统与 Savant/Crestron/C4 并列为选项；若客户已指定四巨头，Vantage 作灯光子系统经驱动集成。旧面板停产款需规划替换造型。', '与四巨头可并存：Vantage=灯光，四巨头=AV/中枢；或互为竞品需选型澄清。', 'E2'::evidence_tier, '[{"url":"https://www.vantagecontrols.com/","note":"Vantage official","fetchedOn":"2026-10-24"},{"url":"http://www.elanportal.com/supportdocs/catalog/g_supported_subsystems_7_1.pdf","note":"ELAN lists Vantage InFusion wired bus","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW010', '01-legacy-plc-bus', 'Centralite LiteJet (Centralized Wired Dimming)', array['centralite', 'litejet', 'centralite litejet', 'centralite elegance']::text[], 'Centralite — 2000–2012 前后北美大宅常见集中式有线调光（LiteJet）与 Elegance 等；后生态收缩，存量改造高频。', '约 1990s–2000s · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '集中调光柜 + 低压/混合按键；常与 OmniPro 等经 RS-232 联动；硬线负载回路集中在机柜。', array['集中柜便于电工维护回路', '曾广泛装于生产住宅/定制宅', '串口状态反馈可行']::text[], array['厂商支持弱、备件风险', '面板造型过时', '升级通常需换柜或换执行层']::text[], array['LiteJet 主机/调光模块', 'Elegance 面板', 'RS-232 接口', '负载扩展']::text[], array['2000–2012 北美大宅继承', '生产住宅升级项目']::text[], '二手模块行情紊乱；整屋替换常按回路重做预算。E3/E4。', '盘点柜内回路图后，优先改 Lutron 柜或 Relay 面板 + 四巨头；RS-232 仅作短期状态桥。', '历史驱动存在于 ELAN 等；新装不选，迁移四巨头灯光。', 'E3'::evidence_tier, '[{"url":"https://cocoontech.com/threads/centralite-litejet-and-omnipro-ii.24099/","note":"LiteJet + OmniPro integration thread","fetchedOn":"2026-10-24"},{"url":"http://www.elanportal.com/supportdocs/catalog/g_supported_subsystems_7_1.pdf","note":"ELAN Centralite support matrix","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW011', '01-legacy-plc-bus', 'Centralite Elegance / Illuminations', array['centralite elegance', 'centralite illuminations', 'centralite hybrid']::text[], 'Centralite 面板与混合 RF/有线产品线（Elegance、Illuminations 等），常与 LiteJet 机柜配套出现在存量宅。', '2000s · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '硬线按键站 + 部分 Hybrid RF；依赖 Centralite 主机逻辑。', array['按键布局灵活', '曾提供混合无线扩展']::text[], array['生态停摆', '与现代面板无法混用', '文档散落论坛']::text[], array['Elegance 面板', 'Illuminations 模块', 'Hybrid RF 扩展']::text[], array['存量 Centralite 住宅局部维修']::text[], '备件二级市场不定价。E4。', '与 NW010 一并评估整柜替换；勿再采购停产面板扩容。', '迁移至 Lutron/Vantage/Savant 面板体系。', 'E3'::evidence_tier, '[{"url":"http://www.elanportal.com/supportdocs/catalog/g_supported_subsystems_7_1.pdf","note":"ELAN lighting matrix","fetchedOn":"2026-10-24"},{"url":"https://cocoontech.com/","note":"CocoonTech Centralite topics","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW012', '01-legacy-plc-bus', 'Touch-Plate (Ultra / Genesis Low-Voltage Lighting)', array['touch-plate', 'touchplate', 'touch plate ultra', 'touchplate genesis', 'touchplate litetouch upgrade']::text[], 'Touch-Plate — 1946 年起的低压两线/继电器灯光控制老牌；现提供 Ultra/Genesis 及 LiteTouch 原线升级服务。', '1946 · ACTIVE_NICHE', 'ACTIVE_NICHE', '低压控制线驱动继电器/调光柜控制市电回路；强调复用既有低压线升级；工厂技师可出差配合本地承包商。', array['历史极长、继电器逻辑直观', '明确支持 LiteTouch 原线升级', '可保留墙内低压线投资']::text[], array['非四巨头生态中心', '全国安装网络有限', 'UI/App 现代化程度一般']::text[], array['Ultra / Genesis 系统', '低压墙开', '继电器柜', 'LiteTouch 升级套件']::text[], array['中世纪现代宅继电器遗产', 'LiteTouch 停产后的替换', '学校/住宅低压灯光']::text[], '升级需 RFQ；FAQ 称不可与 LiteTouch 局部混用。E2。', '继承 LiteTouch/老继电器宅的首选保留线缆替换商之一；若客户要四巨头体验，评估 Lutron HomeWorks 复用低压拓扑的可行性。', '可作灯光执行层替代，或过渡后再接四巨头场景。', 'E2'::evidence_tier, '[{"url":"https://touchplate.com/wp-content/uploads/product-documents/Support/Upgrading-LiteTouch-FAQs.pdf","note":"Official LiteTouch upgrade FAQ","fetchedOn":"2026-10-24"},{"url":"https://touchplate.com/","note":"Touch-Plate site","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW013', '01-legacy-plc-bus', 'GE RR7 / RR9 Low-Voltage Relay Lighting', array['ge rr7', 'ge rr9', 'rr7 relay', 'rr9', 'ge low voltage lighting', 'remcon']::text[], 'GE（及关联 Remcon 等）RR7/RR9 低压机械继电器灯光系统——Mid-Century Modern 北美住宅经典；墙开为低压瞬动，柜内继电器切市电。', '约 1950–1970s 流行 · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '低压（常见 24V 级）瞬时开关脉冲驱动柜内闭锁/非闭锁继电器；星型低压回线至继电器柜；无数字协议。', array['结构简单可靠寿命长', '低压墙开安全性好', '线缆可被现代继电器面板复用']::text[], array['无场景/无状态反馈原生', '继电器噪音与触点老化', '找原规格继电器越来越难']::text[], array['RR7/RR9 继电器', '低压瞬动开关', '变压器与柜', '指示灯配件']::text[], array['中世纪现代住宅', '老公寓公共区灯光', '遗产保护改造']::text[], '继电器单只公开替换件数十美元级；整屋智能化改造另计。E3。', '可保留低压线，换现代继电器面板（Lutron/Crestron/Vantage/Touch-Plate）实现场景；切勿向业主提供市电 DIY 步骤，须持证电工。', '复用低压星型线迁入 Lutron/Crestron 继电器方案为常见路径。', 'E3'::evidence_tier, '[{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"Legacy lighting landscape","fetchedOn":"2026-10-24"},{"url":"https://www.diychatroom.com/","note":"DIYChatroom RR7/RR9 retrofit discussions","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW014', '01-legacy-plc-bus', 'RTI (Remote Technologies Inc. / AVPro)', array['rti', 'rti xp', 'rti icp', 'integration designer', 'rti remote', 'avpro rti']::text[], 'RTI — CEDIA 渠道控制与遥控品牌；XP 系列为传统机柜处理器，较新 ICP 路线；现与 AVPro Global 体系关联销售与支持文档。', '1992 · ACTIVE_NICHE', 'ACTIVE_NICHE', 'Ethernet/IP + IR/RS-232/继电器/传感；Integration Designer 编程；RF 433 / Zigbee 扩展；XP 在 ID12 下多作扩展而非主控。', array['遥控器与触控体验强', '两向驱动库丰富', '适合影音为主的项目']::text[], array['相对 C4/Crestron 市占更小', 'XP 遗产需规划 ICP 迁移', '经销商依赖']::text[], array['XP-3/6/8、ICP 处理器', '手持遥控', 'KX 入墙', 'RM-433/ZM-24', 'RTiPanel']::text[], array['影音优先定制宅', '改造项目用遥控整合多设备']::text[], '处理器公开经销价数百至数千美元；编程费另计。无强制消费订阅。E2。', '可作为四巨头替代控制品牌纳入选型；若客户要统一四巨头，RTI 项目可评估迁移 C4/Crestron 或保留 RTI 作影音岛。', '与四巨头竞品关系；灯光深集成常再挂 Lutron。', 'E2'::evidence_tier, '[{"url":"https://www.avproglobal.com/pages/rti-xp-icp-comparison-utility","note":"XP to ICP comparison","fetchedOn":"2026-10-24"},{"url":"http://cdn.onlinehi-fi.co.nz/brochures/RTI_Control_Processor_Comparison.pdf","note":"RTI processor comparison PDF","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW015', '01-legacy-plc-bus', 'ELAN Home Systems (Nice North America)', array['elan', 'elan gsc', 'elan home systems', 'nice elan', 'nice home management', 'gsc10']::text[], 'ELAN — 定制安装控制品牌；现属 Nice North America；gSC 系列控制器 + 触控/App；支持含 Vantage/Centralite/UPB 等子系统矩阵。', '约 1980s–90s · ACTIVE_NICHE（品牌整合中）', 'ACTIVE_NICHE', 'IP 主控 + IR/串口/继电器；有线/混合灯光子系统驱动；与 Nice 安防/门禁/遮阳版图交叉销售。', array['子系统驱动表较全', 'Nice 集团渠道可打包门窗遮阳', '中端定制市场定位清晰']::text[], array['品牌并购后路线需观察', '高端心智弱于 Crestron/Savant', '编程人才密度一般']::text[], array['gSC 系列控制器', '触控屏', '门铃/对讲集成', '照明/气候驱动包']::text[], array['中高端定制住宅', 'Nice 生态打包项目']::text[], '控制器工程价通常千美元级；项目总包差异大。E3。', '可列为四巨头之外的第五控制选项；若客户只要四巨头，评估驱动迁移成本。', '竞品/并存：可驱 Vantage 灯光同时与 C4 项目竞争同一客户。', 'E2'::evidence_tier, '[{"url":"http://www.elanportal.com/supportdocs/catalog/g_supported_subsystems_7_1.pdf","note":"ELAN supported subsystems 7.1","fetchedOn":"2026-10-24"},{"url":"https://www.niceforyou.com/","note":"Nice group context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW016', '01-legacy-plc-bus', 'URC Total Control (MRX Processors)', array['urc', 'total control', 'urc mrx', 'mrx-12', 'accelerator urc', 'urc professional']::text[], 'Universal Remote Control (URC) Total Control — 专业全屋自动化与网络主控；MRX 系列处理器 + Accelerator / TC Flex 编程。', '1991（遥控起家）· ACTIVE_NICHE', 'ACTIVE_NICHE', 'IP 主控 + IR/RS-232/继电器/传感；两向第三方控制；语音助手集成；机架式处理器。', array['从遥控基因出发的 AV 整合强', 'Accelerator 模板可加快交付', '中型住宅性价比口碑']::text[], array['全球心智不及四巨头', '高端建筑灯光面板弱', '经销商网络地区差']::text[], array['MRX-12 等网络处理器', 'TKP 入墙', 'TDC 桌面', 'TRC 手持', '摄像机/门铃集成']::text[], array['中型定制影音宅', '多区遥控升级全屋']::text[], 'MRX-12 公开经销页列专业编程必需；硬件千美元级。E2。', '选型可并列四巨头中端替代；大灯光需求仍建议 Lutron 子系统。', '竞品关系；可与 Lutron 灯光并存。', 'E2'::evidence_tier, '[{"url":"https://www.awe-europe.com/Brands/URC/Total-Control/System-Processors/URC-MRX-12-Total-Control-Network-Processor-MRX-12","note":"MRX-12 public spec page","fetchedOn":"2026-10-24"},{"url":"https://www.universalremote.com/","note":"URC official","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW017', '01-legacy-plc-bus', 'AMX (Harman / Samsung) NetLinx / Muse', array['amx', 'netlinx', 'amx muse', 'harman amx', 'amx nx']::text[], 'AMX — 商用视听控制巨头，属 Harman（Samsung）；NetLinx 遗产与 Muse 平台；超大庄园/游艇/商住常见。', '1982 · ACTIVE_MAIN（商用）/ ACTIVE_NICHE（住宅）', 'ACTIVE_NICHE', 'NetLinx 总线/IP 控制；大量串口/IR/IO；Muse 为较新平台方向；编程专业门槛高。', array['超大规模 IO 与稳定性质誉', '商用项目经理与程序员池深', '适合 equip 房密集的庄园']::text[], array['住宅美学与消费 App 非长项', '造价与编程费高', '住宅经销商少于 Crestron']::text[], array['NX/NetLinx 控制器', 'Muse 控制器', '触控屏', 'DXLink 传输', 'Enova DVX']::text[], array['超大庄园、庄园多 equip 房', '游艇与商住混合']::text[], '工程项目制，常见数万至数十万美元控制预算。E3。', '超大型项目可与 Crestron 并列选型；中型住宅通常推四巨头住宅线。', '与 Crestron 同场竞技商用基因；住宅场景少见与 C4/Savant 正面撞车。', 'E2'::evidence_tier, '[{"url":"https://www.amx.com/","note":"AMX official","fetchedOn":"2026-10-24"},{"url":"https://www.harman.com/","note":"Harman parent context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW018', '01-legacy-plc-bus', 'Loxone Miniserver / Tree Bus (North America)', array['loxone', 'loxone miniserver', 'loxone tree', 'loxone air', 'loxone usa']::text[], 'Loxone — 奥地利起源的有线总线智能家居；Miniserver + Tree 有线拓扑；北美有分支但渗透低于欧洲。', '2009 · ACTIVE_NICHE', 'ACTIVE_NICHE', 'Tree 有线总线（专用拓扑与供电）+ Air 无线扩展；Miniserver 本地逻辑强；Config 软件可视化编程。', array['本地自动化逻辑强', '水电暖多工种统一总线思路', '欧洲工程方法论清晰']::text[], array['北美经销商与电工认知度低', '备件与认证电工少', '与四巨头渠道隔阂']::text[], array['Miniserver / Miniserver Go', 'Tree 设备', 'Air 设备', '触控与 App', '审计与能源模块']::text[], array['欧式思维新建定制宅', '极客业主全屋总线']::text[], 'Miniserver 公开约数百至千美元；整屋按点位欧元/美元工程计价。E2/E3。', '北美项目慎选除非经销商本地强；否则推四巨头。已装 Loxone 可保留作本地逻辑，AV 交给 Crestron/C4。', '可并存：Loxone 楼宇逻辑 + 四巨头影音。', 'E2'::evidence_tier, '[{"url":"https://www.loxone.com/","note":"Loxone official","fetchedOn":"2026-10-24"},{"url":"https://www.loxone.com/enen/","note":"EN product docs","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW019', '01-legacy-plc-bus', 'Schneider Electric / Clipsal C-Bus', array['c-bus', 'cbus', 'clipsal c-bus', 'schneider c-bus', 'clipsal']::text[], 'Clipsal C-Bus（现 Schneider Electric）——两线自由拓扑有线总线灯光/控制，澳洲起源，北美高定与商住混合可见。', '1990s · ACTIVE_NICHE（北美）', 'ACTIVE_NICHE', 'C-Bus 两线总线（非极性自由拓扑）；开关/调光/继电器单元；网关到 IP/其他协议；偏电气盘柜安装。', array['总线灵活少星型约束', '电气品牌信任背书', '商住项目文档全']::text[], array['北美住宅渠道弱于 Lutron', '面板设计选择相对少', '程序员需专项培训']::text[], array['C-Bus 电源与网关', '开关/调光单元', '触控屏', 'DALI/其他网关']::text[], array['国际业主北美置业', '商住、多套房', '电气总包主导项目']::text[], '按点位工程计价；北美公开零售少。E3。', '已装 C-Bus：经网关挂四巨头；新北美纯住宅优先 Lutron HomeWorks。', '灯光执行层可挂 C4/Crestron/ELAN。', 'E2'::evidence_tier, '[{"url":"http://www.elanportal.com/supportdocs/catalog/g_supported_subsystems_7_1.pdf","note":"ELAN lists Clipsal C-Bus","fetchedOn":"2026-10-24"},{"url":"https://www.se.com/","note":"Schneider Electric","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW020', '01-legacy-plc-bus', 'Schneider Electric Square D (Residential Power / Wiser Context)', array['square d', 'schneider square d', 'square d panel', 'qo load center']::text[], 'Square D（Schneider）——北美配电与断路器主导品牌；与 Energy Center/Wiser 智慧能源线衔接；本身非场景控制器但为有线宅电力骨架。', '1902（Square D）· ACTIVE_MAIN', 'ACTIVE_MAIN', '传统负荷中心 + 智能断路器/监控扩展；干接点/网络接口对接 HEMS 与自动化。', array['电工普及率极高', '与发电机/太阳能配套成熟', '品牌可信度支撑保险与验收']::text[], array['传统面板无场景 UI', '智能升级需专用模块', '与四巨头集成靠第三方']::text[], array['QO/Homeline 负荷中心', '智能断路器', '监控附件', 'Generator 互锁配件']::text[], array['几乎所有北美住宅配电', 'HEMS 升级基座']::text[], '标准 200A 面板公开约数百美元；智能升级另计。无订阅。E1/E2。', '问诊识别配电品牌以便推荐 SPAN/Leviton/Eaton/Schneider Energy Center 升级路径；控制层仍归四巨头。', '电力层合作伙伴，非四巨头竞品。', 'E1'::evidence_tier, '[{"url":"https://www.se.com/us/en/","note":"Schneider Electric US","fetchedOn":"2026-10-24"},{"url":"https://www.energysage.com/energy-management/the-best-smart-panel/","note":"EnergySage smart panel context","fetchedOn":"2026-10-24"}]'::jsonb, true, '2026-10-24'),
('NW021', '01-legacy-plc-bus', 'Philips Dynalite (Signify)', array['dynalite', 'philips dynalite', 'signify dynalite', 'dyanet']::text[], 'Philips Dynalite（Signify）——有线灯光总线与建筑控制，DyNet 等；北美多见于高定/商业下放住宅。', '约 1980s（Dynalite 澳）· ACTIVE_NICHE', 'ACTIVE_NICHE', 'DyNet 有线总线 + DALI/KNX/DMX 网关；Antumbra 等面板；IP 集成；近年提及 Matter 网关方向。', array['建筑级灯光与遮阳整合强', '协议网关丰富', '国际项目延续性好']::text[], array['北美 CEDIA 心智弱于 Lutron', '住宅经销商密度低', '造价与培训门槛']::text[], array['Dynalite 控制器', 'Antumbra 面板', 'DALI 网关', '传感器', 'PD 系列负载']::text[], array['国际设计师项目', '商住、美术馆式住宅']::text[], '工程计价；公开零售少。E2/E3。', '可作灯光子系统经网关进 Crestron/C4；纯北美客户通常仍荐 Lutron。', '灯光子系统角色对接四巨头。', 'E2'::evidence_tier, '[{"url":"https://dynalite.com/integrations/","note":"Dynalite integrations","fetchedOn":"2026-10-24"},{"url":"https://www.signify.com/","note":"Signify parent","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW022', '01-legacy-plc-bus', 'Crestron Pyng (Historical Residential Platform)', array['crestron pyng', 'pyng', 'crestron pyng hub', 'pyng legacy']::text[], 'Crestron Pyng — 曾面向简化住宅配置的过渡平台/中枢；现属历史架构，新项目以 Crestron Home / 传统 Crestron 编程为主。', '2010s · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '简化配置层 + Crestron 设备生态；IP 设备发现与场景；非完整替代传统 SIMPL/Crestron Home 的长期路线。', array['降低部分住宅项目编程门槛', '仍属 Crestron 设备兼容圈']::text[], array['平台生命周期已过高峰', '文档与经销商心智转向 Crestron Home', '扩容需确认当前支持路径']::text[], array['Pyng Hub 相关硬件', '兼容灯光/遮阳/AV 设备包']::text[], array['2010s Crestron 简化住宅存量']::text[], '存量维护；新购不推荐。E3。', '识别为 Crestron 家族遗产；升级路径评估 Crestron Home 或完整 Crestron。属四巨头内部演进而非外部竞品。', '四巨头内部：迁到现行 Crestron 住宅平台。', 'E3'::evidence_tier, '[{"url":"https://www.crestron.com/","note":"Crestron official (current platforms)","fetchedOn":"2026-10-24"},{"url":"https://www.crestron.com/Products","note":"Product transition context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW023', '01-legacy-plc-bus', 'Bang & Olufsen Beolink / Master Link Ecosystem', array['bang olufsen', 'beolink', 'b&o', 'masterlink', 'beonet', 'bo power link']::text[], 'Bang & Olufsen — 丹麦高端音响；Beolink/Master Link 等有线主从互联遗产；现代靠网络 API / 合作驱动接入第三方控制。', '1925（公司）· ACTIVE_MAIN（音响）/ LEGACY_MAINTENANCE（旧 Beolink 总线）', 'ACTIVE_NICHE', '经典 Power Link / Master Link 专有有线音频分配；现代产品转网络流媒体 + 官方第三方驱动框架；旧总线网关多已过时。', array['声学与工业设计顶级', '豪宅影音岛差异化', '官方维护第三方控制路径']::text[], array['旧 Beolink 总线难扩容', '造价极高', '全屋灯光安防非其主业']::text[], array['Beolab 音箱', 'Beosound', '旧 Master Link 产品', '第三方控制 API']::text[], array['豪华影音室', '设计师住宅音响岛']::text[], '单件数千至数万美元；无安防订阅。E2。', '音响岛保留 B&O，全屋中枢用 Crestron/Savant/C4（官方驱动列表见支持文）。勿用旧总线扩全屋。', '作为 AV 子系统接入四巨头，非中枢竞品。', 'E2'::evidence_tier, '[{"url":"https://support.bang-olufsen.com/hc/en-us/articles/360049859212-Drivers-for-3rd-Party-integration","note":"B&O third-party drivers","fetchedOn":"2026-10-24"},{"url":"https://www.bang-olufsen.com/","note":"B&O official","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW024', '01-legacy-plc-bus', 'Josh.ai (Josh Core PoE Voice Hub)', array['josh.ai', 'josh ai', 'josh core', 'josh micro', 'josh.ai voice']::text[], 'Josh.ai — 本地优先的豪华语音与智能中枢；Josh Core 等 PoE/有线主机；与众多 CEDIA 品牌认证集成。', '2015 · ACTIVE_NICHE', 'ACTIVE_NICHE', 'PoE/有线主机本地 NLU；IP 集成 Control4/Crestron/Savant/Lutron/B&O 等；强调隐私与豪宅多房间语音。', array['豪华语音体验与本地处理', '与四巨头认证合作清晰', '适合已有有线中枢的上层体验']::text[], array['价格与订阅/许可需确认经销条款', '依赖底层已做好的子系统', '非照明电力执行层']::text[], array['Josh Core', 'Josh Micro', '麦克风套件', 'App 与语音人格配置']::text[], array['已有四巨头的豪宅语音层', '新建高定体验升级']::text[], '硬件与软件许可经销报价，常见数千美元级+。E3。', '定位为四巨头之上的语音/体验层，而非替代；问诊时作增强项推荐。', '增强四巨头，不替换四巨头。', 'E2'::evidence_tier, '[{"url":"https://support.josh.ai/hc/en-us/articles/53098634981652-Josh-ai-Certified-Partners","note":"Josh.ai certified partners","fetchedOn":"2026-10-24"},{"url":"https://www.josh.ai/","note":"Josh.ai official","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW025', '01-legacy-plc-bus', 'Legrand On-Q Structured Wiring', array['on-q', 'onq', 'legrand on-q', 'on-q enclosure']::text[], 'Legrand On-Q — 结构化布线与多媒体箱竞品线；与 Vantage/Legrand 电气体系同集团。', '1990s · ACTIVE_MAIN', 'ACTIVE_MAIN', '星型弱电汇聚箱与模块；同 Leviton SMC 类似的物理层角色。', array['与 Legrand 电气/Vantage 渠道协同', '配件标准化']::text[], array['无智能逻辑', '需规范端接']::text[], array['On-Q 箱', '数据/视频模块', '电源模块']::text[], array['新建弱电', '翻新星型布线']::text[], '箱体公开约 USD $50–$250。无订阅。E1。', '同 SMC：保留为四巨头与安防布线资产。', '基础设施，非竞品。', 'E1'::evidence_tier, '[{"url":"https://www.legrand.us/","note":"Legrand US On-Q","fetchedOn":"2026-10-24"},{"url":"https://www.homedepot.com/","note":"Retail On-Q enclosures","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW026', '01-legacy-plc-bus', 'NuVo (Legacy Multiroom Wired Audio)', array['nuvo', 'nuvo multiroom', 'nuvo grand concerto', 'nuvo essentia', 'legrand nuvo']::text[], 'NuVo — 全屋有线多房音频老牌（后入 Legrand 等体系）；功放机柜 + 专用键盘；存量常见。', '1990s · LEGACY_MAINTENANCE / 部分 ACTIVE_NICHE', 'LEGACY_MAINTENANCE', '模拟/数字多区功放 + 猫5 控制键盘；源设备切换；非流媒体原生年代产品居多。', array['独立多区功放可靠', '墙控简单老人友好']::text[], array['流媒体时代体验落后', '键盘协议专有', '升级常换 Sonos Amp/Russound/Autonomic']::text[], array['Grand Concerto/Essentia 等功放', 'NuVo 键盘', '源切换']::text[], array['2000s 多房音乐宅存量']::text[], '二手与清仓不定；替换项目按区 $500–$2000+。E3。', '保留喇叭线，换 Sonos Amp 阵列或 Russound/Autonomic + 四巨头控制。', '音频子系统替换后接入四巨头。', 'E3'::evidence_tier, '[{"url":"https://www.legrand.us/","note":"Legrand/NuVo heritage","fetchedOn":"2026-10-24"},{"url":"https://www.crutchfield.com/","note":"Crutchfield multiroom context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW027', '01-legacy-plc-bus', 'Niles Audio (Legacy Multiroom / IR)', array['niles', 'niles audio', 'niles intellicontrol', 'niles zr', 'speakerCraft niles']::text[], 'Niles Audio — 多房音频、IR 路由与扬声器品牌；存量 IR/多区功放常见于 90–2010s 定制宅。', '1978 · LEGACY_MAINTENANCE（多线）', 'LEGACY_MAINTENANCE', 'IR 重复/路由、扬声器选择器、多区功放；模拟音频分配为主。', array['喇叭与IR基础设施可复用', '安装商熟悉']::text[], array['数字流媒体弱', '控制协议老旧']::text[], array['ZR 多区', 'IR 路由', '户内喇叭', '选择器']::text[], array['存量多房音频改造']::text[], '替换导向报价。E3。', '保留扬声器线，控制与功放现代化后交四巨头。', '子系统现代化后挂四巨头。', 'E3'::evidence_tier, '[{"url":"https://www.crutchfield.com/","note":"Crutchfield Niles category historically","fetchedOn":"2026-10-24"},{"url":"https://www.avsforum.com/","note":"AVSForum Niles retrofit threads","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW028', '01-legacy-plc-bus', 'SpeakerCraft (Architectural Speakers / Legacy Control)', array['speakercraft', 'speaker craft', 'speakercraft mzm']::text[], 'SpeakerCraft — 建筑扬声器与部分多区控制遗产；现多作为扬声器层出现在改造中。', '1976 · ACTIVE_NICHE（喇叭）/ LEGACY（旧控制）', 'ACTIVE_NICHE', '吸顶/户外扬声器为主；旧多区控制协议存量。', array['建筑扬声器型号全', '改造可留喇叭换功放']::text[], array['旧控制脑停产', '数字流媒体与App体验落后于现代多房方案']::text[], array['AES/Profile 等喇叭系列', '旧 MZ 控制器']::text[], array['全屋音乐扬声器层']::text[], '喇叭单只数十至数百美元。E2/E3。', '保留喇叭，功放改 Sonos Amp/AudioControl/Russound + 四巨头。', '扬声器层，非中枢。', 'E3'::evidence_tier, '[{"url":"https://www.speakercraft.com/","note":"SpeakerCraft official","fetchedOn":"2026-10-24"},{"url":"https://www.crutchfield.com/","note":"Retail architectural speakers","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW029', '01-legacy-plc-bus', 'PCS PulseWorx (UPB Branding)', array['pulseworx', 'pcs pulseworx', 'pulse worx']::text[], 'PCS PulseWorx — UPB 协议下的产品品牌线，常与 HAI/Simply Automated 并存于存量。', '1999+ · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', 'UPB PPM 电力线控制，同 NW002。', array['UPB 可靠性', '双向']::text[], array['生态停滞', '备件']::text[], array['PulseWorx 开关/调光', '接口']::text[], array['UPB 存量维护']::text[], '同 UPB 模组价位。E3。', '同 NW002 迁移建议。', '过渡后迁四巨头灯光。', 'E3'::evidence_tier, '[{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"UPB/PulseWorx context","fetchedOn":"2026-10-24"},{"url":"https://cocoontech.com/","note":"Forum","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW030', '01-legacy-plc-bus', 'BitWise Controls (BC Controllers)', array['bitwise', 'bitwise controls', 'bc1', 'bc4', 'bitwise bc']::text[], 'BitWise Controls — 中小型定制控制与触控界面品牌；BC 系列控制器；偏中端 CEDIA。', '2000s · ACTIVE_NICHE', 'ACTIVE_NICHE', 'IP/IR/串口控制；自研界面工具；机架控制器。', array['界面定制灵活', '中端造价']::text[], array['生态与人才池小于四巨头', '长期并购/路线风险需核查']::text[], array['BC 控制器', '触控屏', 'App']::text[], array['中型影音控制项目']::text[], '控制器公开经销价数百–数千美元。E3。', '可作中端替代；大宅仍推四巨头。', '竞品/替代选项。', 'E3'::evidence_tier, '[{"url":"https://www.bitwisecontrols.com/","note":"BitWise official","fetchedOn":"2026-10-24"},{"url":"https://chowmain.software/for-manufacturers/driver-development","note":"Driver ecosystem context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW031', '01-legacy-plc-bus', 'Clare Controls (Legacy Smart Home OS)', array['clare', 'clare controls', 'clarehome', 'clareone']::text[], 'Clare Controls — 曾主打经销商云+本地的智能家居 OS 与面板；市场收缩后存量需谨慎评估支持。', '2010s · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', 'IP 中枢 + 触控/App；混合无线与有线外设。', array['曾提供统一 App 体验', '公开渠道/工程文档可核查']::text[], array['支持与经销商不确定性', '扩容风险']::text[], array['ClareOne 面板', '控制器', '摄像头集成']::text[], array['2010s 中端智能宅存量']::text[], '存量维护为主。E4。', '评估是否迁移 C4/Savant；安防部分看是否 Alarm.com 底层。', '迁移四巨头。', 'E4'::evidence_tier, '[{"url":"https://www.clarecontrols.com/","note":"Clare site if active","fetchedOn":"2026-10-24"},{"url":"https://www.reddit.com/r/homeautomation/","note":"Community status discussions","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW032', '01-legacy-plc-bus', 'Autonomic Controls (Mirage Audio Servers)', array['autonomic', 'mirage mms', 'autonomic mirage', 'mms-5a']::text[], 'Autonomic — 全屋音频服务器 Mirage 系列；机柜有线流媒体源，常被四巨头驱动。', '2000s · ACTIVE_NICHE', 'ACTIVE_NICHE', '以太网音频服务器；多流解码；模拟/数字输出进功放矩阵。', array['多房间流媒体源稳定', '与 Crestron/C4/Savant 集成成熟']::text[], array['需优质网络', '授权与服务条款需经销确认']::text[], array['Mirage MMS 服务器', '放大器接口', '流媒体服务授权']::text[], array['豪宅多房音频源']::text[], '服务器数千美元级+服务。E2。', '作为音频源子系统接入四巨头，推荐保留。', '四巨头音频源伙伴。', 'E2'::evidence_tier, '[{"url":"https://www.autonomic-controls.com/","note":"Autonomic official","fetchedOn":"2026-10-24"},{"url":"https://chowmain.software/for-manufacturers/driver-development","note":"Integration context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW033', '01-legacy-plc-bus', 'Pro Control (URC Sister / Controllers)', array['pro control', 'procontrol', 'pro24', 'urc pro control']::text[], 'Pro Control — 与 URC 关联的定制控制/遥控产品线；面向经销商编程项目。', '2000s · ACTIVE_NICHE', 'ACTIVE_NICHE', 'IP/IR/串口处理器与遥控；专业软件编程。', array['遥控与界面包完整', '中端项目交付快']::text[], array['品牌声量区域化', '灯光深控弱']::text[], array['处理器', '遥控', '触控']::text[], array['中型 AV 控制']::text[], '工程报价。E3。', '中端替代；大灯光仍挂 Lutron。', '竞品/中端替代。', 'E3'::evidence_tier, '[{"url":"https://www.procontrol.com/","note":"Pro Control official","fetchedOn":"2026-10-24"},{"url":"https://www.universalremote.com/","note":"URC related ecosystem","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW034', '01-legacy-plc-bus', 'Key Digital Compass Control', array['key digital', 'compass control', 'key digital compass', 'kd compass']::text[], 'Key Digital — 视频分配与 Compass Control 控制平台；HDBaseT/矩阵基因强。', '1990s+ · ACTIVE_NICHE', 'ACTIVE_NICHE', 'IP 控制 + 视频矩阵/HDBaseT 深度整合；IR/串口。', array['视频链路与控制一体', '适合影音机柜密集项目']::text[], array['全屋灯光安防非主场', '品牌心智偏视频']::text[], array['Compass 控制器', '矩阵与延长器', 'App']::text[], array['家庭影院 + 多显']::text[], '工程报价。E3。', '影音岛方案；全屋中枢仍推四巨头。', 'AV 子系统/中端中枢替代。', 'E3'::evidence_tier, '[{"url":"https://www.keydigital.com/","note":"Key Digital official","fetchedOn":"2026-10-24"},{"url":"https://www.avsforum.com/","note":"AVSForum discussions","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW035', '01-legacy-plc-bus', 'Lutron GRAFIK Eye / LP (Legacy Wired Preset)', array['grafik eye', 'grafikeye', 'lutron grafik', 'lutron lp', 'grafik eye qs']::text[], 'Lutron GRAFIK Eye — 经典有线预置调光站（非完整 HomeWorks）；大量存量商业与住宅；QS 等演化。注意：完整 HomeWorks 属四巨头主线，本条仅覆盖 GRAFIK 预置遗产识别。', '1990s · ACTIVE_NICHE（遗产维护/部分在产演化）', 'ACTIVE_NICHE', '有线预置场景站 + 功率模块；链路通信；常被误认为整屋 HomeWorks。', array['可靠预置场景', 'Lutron 支持体系仍强', '可升级进更大 Lutron 体系']::text[], array['单站能力有限非全屋 OS', '易与 HomeWorks 混淆导致错误报价']::text[], array['GRAFIK Eye 单元', '功率接口', '遥控/辅助控件']::text[], array['会议室/餐厅预置', '住宅分区预置存量']::text[], '单站公开工程价数百–数千美元。E2。', '识别后评估并入 HomeWorks QSX 或保留分区预置 + 四巨头场景调用。', 'Lutron 家族内部升级，非外部竞品。', 'E2'::evidence_tier, '[{"url":"https://www.lutron.com/","note":"Lutron official","fetchedOn":"2026-10-24"},{"url":"https://hometoys.com/a-brief-technology-overview-of-the-lighting-control-marketplace/","note":"Marketplace context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW036', '01-legacy-plc-bus', 'Lightolier Controls / by Signify (Legacy Architectural)', array['lightolier', 'lightolier controls', 'compose', 'lytemode']::text[], 'Lightolier Controls — 建筑调光遗产品牌（Compose/Lytemode 等），现处 Signify 版图；北美商业/住宅存量。', '20世纪中后 · LEGACY_MAINTENANCE', 'LEGACY_MAINTENANCE', '有线建筑调光与预设；机柜模块。', array['建筑项目常见', '与灯具品牌历史协同']::text[], array['住宅 App 生态弱', '备件与升级路径需个案']::text[], array['Compose/Lytemode 模块', '站控']::text[], array['建筑灯光存量']::text[], '工程维护报价。E4。', '评估改 Lutron/Dynalite/Vantage；保留回路重做控制。', '迁移现代灯光品牌后接四巨头。', 'E4'::evidence_tier, '[{"url":"https://www.signify.com/","note":"Signify brand house","fetchedOn":"2026-10-24"},{"url":"https://www.lightolier.com/","note":"Lightolier heritage","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW037', '01-legacy-plc-bus', 'Wattstopper / Legrand Lighting Controls (Commercial Wired)', array['wattstopper', 'watt stopper', 'legrand wattstopper', 'digital lighting management']::text[], 'Wattstopper（Legrand）——商业有线照明控制与节能传感器；大宅机电房偶见。', '1980s · ACTIVE_MAIN（商业）', 'ACTIVE_NICHE', '有线继电器/调光面板 + 占用/日照传感总线；DLM 等数字照明管理。', array['节能合规强', '传感器质量口碑']::text[], array['住宅场景 UI 弱', '偏机电而非 CEDIA 体验']::text[], array['DLM 房间控制器', '传感器', '面板']::text[], array['大型住宅机电节能', '附楼/车库照明']::text[], '工程计价。E2。', '作机电照明层，场景体验交给 Lutron/四巨头。', '执行/节能层，挂四巨头场景。', 'E2'::evidence_tier, '[{"url":"https://www.legrand.us/","note":"Legrand Wattstopper","fetchedOn":"2026-10-24"},{"url":"https://www.wattstopper.com/","note":"Wattstopper site","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW038', '01-legacy-plc-bus', 'ESI / iLight / Cooper Wired Lighting (Legacy Names)', array['esi lighting', 'ilight', 'cooper lighting controls', 'eaton lighting controls']::text[], 'ESI/iLight 及 Cooper/Eaton 灯光控制等北美商业有线名称，存量文档与 ELAN 矩阵可见。', '多年商业线 · LEGACY_MAINTENANCE / ACTIVE_NICHE', 'LEGACY_MAINTENANCE', '硬线负载控制与专用网络；品牌多次并购改名。', array['商业项目文档多', '公开渠道/工程文档可核查']::text[], array['品牌名混乱导致备件难寻', '住宅体验差']::text[], array['iCan 等硬线设备', '机柜模块']::text[], array['商住混合存量']::text[], '个案。E4。', '以回路图为准重做至 Lutron 或保留继电器接四巨头。', '迁移后接四巨头。', 'E4'::evidence_tier, '[{"url":"http://www.elanportal.com/supportdocs/catalog/g_supported_subsystems_7_1.pdf","note":"ELAN iLight hardwired note","fetchedOn":"2026-10-24"},{"url":"https://www.eaton.com/","note":"Eaton lighting controls context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW039', '02-security-managed-platforms', 'Alarm.com (Managed Security & Automation Platform)', array['alarm.com', 'alarmcom', 'adc', 'alarm.com dealer', 'surety']::text[], 'Alarm.com — 北美最大交互式安防/智能后台使能平台；不直接toC卖硬件，通过本地经销商/中央站赋能 2GIG、Qolsys、DSC 等面板。', '2000 · ACTIVE_MAIN', 'ACTIVE_MAIN', '云+蜂窝/IP 双路径；面板经模块上云；视频、门锁、恒温、车库等自动化规则；经销商 RMR 模式。', array['经销商网络极广', '蜂窝备份与专业值守成熟', '视频与自动化规则强']::text[], array['云依赖与隐私顾虑', '与本地四巨头权限边界需划清', '月费结构复杂']::text[], array['经销商面板生态（Qolsys/2GIG等）', 'ADC 视频', '能源/自动化技能', '经销商门户']::text[], array['专业安装安防住宅', 'RMR 运营项目', '中产到豪宅安防层']::text[], '硬件因套餐而异；监控+交互常见约 USD $30–$70+/月（公开媒体口径）。fetched_on 2026-10-24。', '安防运营层可与 Control4/Crestron/Lutron 并存：明确 ADC 管安防视频，四巨头管灯光AV；或用官方/社区集成有限互通。不要指望 ADC 替代 HomeWorks。', '边界集成：安防归 ADC，体验中枢归四巨头。', 'E1'::evidence_tier, '[{"url":"https://www.alarm.com/","note":"Alarm.com official","fetchedOn":"2026-10-24"},{"url":"https://community.hubitat.com/t/house-alarm-in-2025/157097","note":"2025 integration discussions","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW040', '02-security-managed-platforms', 'ADT (Command / Professional Monitoring)', array['adt', 'adt command', 'adt commercial', 'adt blue', 'adt pulse']::text[], 'ADT — 北美最大安防运营商品牌之一；传统硬线改造 + Command 面板；含商业线与消费合作线（历史上与 Google Nest 等合作宣传）。', '1874 · ACTIVE_MAIN', 'ACTIVE_MAIN', '有线/混合防区 + 专有/合作面板；中央站值守；蜂窝/IP；部分方案基于主流面板芯片组。', array['品牌与值守网络强大', '合同与保险折扣路径熟', '全国安装产能']::text[], array['合同绑定与解约成本', '定制灯光AV弱', '开放集成有限']::text[], array['Command 面板', '门窗传感', '摄像头套餐', '商业火警联动']::text[], array['主流美国家庭安防订阅', '改造传统硬线防区']::text[], '设备费+安装差异大；监控月费公开常见约 $30–$60+。E2/E3。', '大宅若要四巨头体验：安防可留 ADT 值守或改为 Elk/DMP+本地集成商；避免 ADT 闭包阻碍灯光中枢。', '安防运营竞品；与四巨头边界共存。', 'E2'::evidence_tier, '[{"url":"https://www.adt.com/","note":"ADT official","fetchedOn":"2026-10-24"},{"url":"https://www.alarm.com/","note":"Often underlying tech via partners","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW041', '02-security-managed-platforms', 'Vivint Smart Home', array['vivint', 'vivint smart home', 'vivint panel', 'vivint sky']::text[], 'Vivint — 直营安装的封闭端到端智能安防家居；高月费与设备融资模式常见。', '1999 · ACTIVE_MAIN', 'ACTIVE_MAIN', '专有面板+传感器+摄像头；云App；专业安装；生态相对封闭。', array['一站式安装体验', '销售与装机流程标准']::text[], array['封闭难接四巨头', '合同/融资争议口碑', 'DIY 改造空间小']::text[], array['Vivint 智能面板', '门铃摄像', '门锁', '传感器包']::text[], array['郊区成套智能安防销售']::text[], '设备+月费捆绑，公开报道常见高月费档。E3。', '一般不建议作为豪宅有线中枢；若已装，评估解约成本后迁移安防至开放面板+四巨头。', '封闭竞品，难桥四巨头。', 'E3'::evidence_tier, '[{"url":"https://www.vivint.com/","note":"Vivint official","fetchedOn":"2026-10-24"},{"url":"https://www.reddit.com/r/homeautomation/","note":"User contract/integration discussions","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW042', '02-security-managed-platforms', 'Resideo Honeywell Home VISTA-20P', array['vista-20p', 'vista 20p', 'honeywell vista', 'resideo vista', 'vista20p']::text[], 'Resideo（原 Honeywell Home 安防）VISTA-20P — 北美最常见有线安防主机之一，豪宅地下室‘白盒’标配级存量。', '1990s– · ACTIVE_NICHE（仍广泛维护）', 'ACTIVE_NICHE', '传统有线防区（常见 8 基本+扩展）；辅助继电器；经蜂窝/IP 通信器上中央站；可编程区划。', array['硬线可靠、电工/安防商人人会', '扩展配件市场大', '可经 EnvisaLink/Konnected 智能化']::text[], array['原生 App 体验弱', '编程依赖 * 码与软件', '非现代触控 UX']::text[], array['VISTA-20P 主机', '6160 键盘', '防区扩展', '通信器模块']::text[], array['存量有线安防', '出租与自住房改造']::text[], '主机公开约 USD $100–$200；键盘/扩展另计；监控月费另计。E1/E2。', '保留硬线传感，上 EnvisaLink 或 Konnected，或换 Elk/ProSeries；四巨头经驱动/继电器布防联动。', '经典有线防区层，桥四巨头。', 'E1'::evidence_tier, '[{"url":"https://www.eyezon.com/","note":"EnvisaLink compatible Vista list","fetchedOn":"2026-10-24"},{"url":"https://konnected.io/","note":"Retrofit wired panels","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW043', '02-security-managed-platforms', 'Resideo VISTA-128BPT / High-Zone VISTA', array['vista-128', 'vista 128bpt', 'vista128', 'honeywell 128bpt']::text[], 'VISTA-128BPT 等高防区 VISTA — 大宅/小型商业有线主机，防区与分区能力远超 20P。', '1990s– · ACTIVE_NICHE', 'ACTIVE_NICHE', '高防区有线总线/扩展架构；多分区；商住混合编程模型。', array['大宅防区容量', '成熟稳定']::text[], array['编程复杂', '触控体验依赖第三方', '备件与通信器需规划']::text[], array['128BPT 主机', '扩展模块', '商用键盘']::text[], array['大型别墅硬线安防', '家庭办公室']::text[], '主机数百美元级；工程安装为主。E2。', '同 20P：保留线，现代化通信与中枢联动；或迁 DMP/Elk。', '大容量有线防区，桥四巨头。', 'E2'::evidence_tier, '[{"url":"https://www.eyezon.com/","note":"Compatible panel list includes 128P class","fetchedOn":"2026-10-24"},{"url":"https://www.resideo.com/","note":"Resideo security","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW044', '02-security-managed-platforms', 'Resideo V-Plex (Two-Wire Polling Loop)', array['v-plex', 'vplex', 'honeywell v-plex', 'vista v-plex']::text[], 'V-Plex — Honeywell/Resideo 两线轮询寻址防区总线，减少多线星型回线。', '1990s · ACTIVE_NICHE', 'ACTIVE_NICHE', '两线轮询回路上挂寻址门磁/模块；与 VISTA 主机配合；拓扑省线。', array['省线适合改建', '寻址便于定位']::text[], array['专有模块成本', '故障排查需专用知识', '混用普通干接点需模块']::text[], array['V-Plex 门磁/模块', '回路电源与隔离']::text[], array['大宅改建省线安防']::text[], '模块单价高于普通门磁。E3。', '保留 V-Plex 回路或逐步改为普通硬线+Konnected；与四巨头联动仍在主机层。', '总线防区层。', 'E3'::evidence_tier, '[{"url":"https://www.resideo.com/","note":"Resideo V-Plex docs","fetchedOn":"2026-10-24"},{"url":"https://www.alarmgrid.com/","note":"Alarm Grid educational pages","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW045', '02-security-managed-platforms', 'Resideo ProSeries (ProHub / Modern Platform)', array['proseries', 'resideo proseries', 'pro hub', 'honeywell proseries']::text[], 'Resideo ProSeries — 较新的安防/智能平台，面向经销商的现代化面板与传感器生态。', '2010s 末– · ACTIVE_MAIN', 'ACTIVE_MAIN', 'IP/蜂窝面板；加密传感；App 与经销商服务；逐步承接 VISTA 世代。', array['现代 UX', '经销商支持路径清晰']::text[], array['与老 VISTA 线缆不完全无缝', '生态仍偏安防而非全屋灯光']::text[], array['ProSeries 面板', '传感器', '通信模块']::text[], array['新装专业安防', 'VISTA 升级替代']::text[], '套装+月费模式。E2。', '新装安防可选；全屋体验仍接四巨头。', '现代安防层+四巨头。', 'E2'::evidence_tier, '[{"url":"https://www.resideo.com/","note":"Resideo ProSeries","fetchedOn":"2026-10-24"},{"url":"https://www.alarm.com/","note":"Platform competition context","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW046', '02-security-managed-platforms', 'Elk Products M1 Gold', array['elk m1', 'elk m1 gold', 'm1gold', 'elk products', 'elkrp']::text[], 'Elk M1 Gold — 发烧级有线安防与自动化主机；RS-485 扩展；以强本地逻辑和四巨头串口/IP 互通著称。', '约 2000s · ACTIVE_NICHE', 'ACTIVE_NICHE', '有线防区 + RS-485 M1X 扩展；规则引擎；以太网控制；大量第三方驱动（C4/Crestron/HA）。', array['本地逻辑极强不靠云', '与四巨头集成口碑顶尖', '安防与继电器自动化一体']::text[], array['UX 需第三方触控/App', '编程学习曲线', '非大众连锁安装']::text[], array['M1 Gold 主机', 'M1XEP 以太网', '扩展板', '键盘', '继电器']::text[], array['极客豪宅', '要本地安防+自动化的项目']::text[], '主机公开约 USD $500–$900；扩展另计；无强制云订阅。E1/E2。', '强烈推荐作为开放有线安防底座对接四巨头；保留所有硬线传感。', '最佳四巨头安防伙伴之一。', 'E1'::evidence_tier, '[{"url":"https://www.elkproducts.com/","note":"Elk official","fetchedOn":"2026-10-24"},{"url":"https://www.reddit.com/r/homeassistant/comments/1o11by8/standalone_alarm_system_to_integrate_with_ha/","note":"2025 HA users praise M1","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW047', '02-security-managed-platforms', 'Elk M1 Cross / Automation Expansions', array['elk m1 cross', 'm1xsp', 'm1xo', 'elk automation']::text[], 'Elk M1 生态扩展（串口、输出、照明协议桥等），支撑灯光/温控等自动化。', '2000s · ACTIVE_NICHE', 'ACTIVE_NICHE', 'RS-485/串口扩展总线；可桥接部分灯光协议与继电器场景。', array['扩展模块化', '本地可靠']::text[], array['模块成本累积', '复杂编程']::text[], array['M1XSP', '输出扩展', '照明接口']::text[], array['M1 系统扩容']::text[], '模块数十至数百美元。E2。', '与 NW046 一并作为四巨头本地 IO 层。', '四巨头 IO 伙伴。', 'E2'::evidence_tier, '[{"url":"https://www.elkproducts.com/","note":"Elk expansions","fetchedOn":"2026-10-24"},{"url":"https://cocoontech.com/","note":"Classic Elk community","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('NW048', '02-security-managed-platforms', 'DMP XR150', array['dmp', 'dmp xr150', 'digital monitoring products', 'xr150']::text[], 'DMP（Digital Monitoring Products）XR150 — 美制专业有线/混合安防主机，银行与豪宅渠道。', '1979（公司）· ACTIVE_MAIN', 'ACTIVE_MAIN', '有线防区+无线扩展；网络/蜂窝通信；加密与商业功能；经销商编程。', array['专业级可靠性', '商业功能下放到住宅', '监控商支持好']::text[], array['消费 App 生态不如 ADC 炫', '经销商依赖', '价格偏专业市场']::text[], array['XR150 主机', '键盘', '无线接收', '通信模块']::text[], array['豪宅与小型商业', '保险要求高的项目']::text[], '工程经销价。E2。', '作专业安防层；经干接点/驱动联四巨头。', '专业安防+四巨头联动。', 'E2'::evidence_tier, '[{"url":"https://www.dmp.com/","note":"DMP official","fetchedOn":"2026-10-24"},{"url":"https://community.hubitat.com/t/house-alarm-in-2025/157097","note":"DMP+Konnected mentions","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
