('NW057', '02-security-managed-platforms', 'Konnected Alarm Panel Interface (PoE / Wired Retrofit)', array['konnected', 'konnected.io', 'alarm panel pro', 'konnected alarm']::text[], 'Konnected — 将传统别墅有线门磁/红外防区转为智能信号的改造板；强调本地、无强制订阅；支持 HA/Hubitat/SmartThings 等。', '2010s · ACTIVE_NICHE', 'ACTIVE_NICHE', '并入原报警箱，接管 zone 回路为干接点/GPIO 网络设备；PoE/Wi-Fi 型号；可选云。', array['盘活墙内硬线', '无强制月费', '本地集成一流']::text[], array['本身不是 UL 中央站替代叙事需对外说清', '需合理供电与箱内工艺', '关键生命安全报警需合规评估']::text[], array['Alarm Panel 接口板', 'Interface Panel', 'Garage door 模块']::text[], array['老报警箱智能化', '取消月费但留传感器']::text[], '板卡公开约 USD $100–$300+。无强制订阅。E1。', '继承房神器：保留门窗线，信号进四巨头或本地中枢；专业值守需求另配合规主机。', '改造桥：硬线防区→四巨头/HA。', 'E1'::evidence_tier, '[{"url":"https://konnected.io/","note":"Konnected official","fetchedOn":"2026-10-24"},{"url":"https://www.reddit.com/r/homeassistant/comments/1o11by8/standalone_alarm_system_to_integrate_with_ha/","note":"HA community recommendation","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
