('NW069', '03-hems-smart-panels', 'SPAN Smart Electrical Panel', array['span', 'span.io', 'span panel', 'span panel 48', 'span smart panel']::text[], 'SPAN.io — 硅谷智能配电箱，整箱替换主配电；逐回路计量与控制；动态切负荷；前特斯拉工程师团队创立叙事。', '2018 · ACTIVE_MAIN', 'ACTIVE_MAIN', '数字化断路器总线面板（32/48 回路）；App 分类 Must/Nice/Non-essential；停电与储能联动切负荷；以太网/Wi-Fi 上云与本地控制混合。', array['逐回路可视与控制体验业界标杆', '可辅助避免部分服务升级', '储能续航优化宣传强']::text[], array['面板贵、需持证电工整箱替换', '长期维修生态仍在发展', '高级功能依赖网络']::text[], array['SPAN Panel 32/48', 'SPAN Drive EV', 'App 能源管理']::text[], array['光储充别墅', '全屋电气化改造', '科技豪宅配电']::text[], '面板硬件公开约 USD $3,500；含安装常见可达 $5k–$10k（EnergySage 等媒体口径 2024–2026）。无强制安防式月费。E2。', '须持证电工；可与 Savant/Control4 等探讨集成现状。配电智能化不替代四巨头灯光场景，宜并存。', '能源层伙伴；与 Savant/C4 有集成讨论，非灯光中枢替代。', 'E2'::evidence_tier, '[{"url":"https://www.energysage.com/energy-management/the-best-smart-panel/","note":"EnergySage smart panel comparison","fetchedOn":"2026-10-24"},{"url":"https://www.wattbuild.com/learn/about/96/smart-electrical-panels","note":"SPAN technical overview","fetchedOn":"2026-10-24"}]'::jsonb, true, '2026-10-24'),
