('WL001', '01-protocols-and-hubs', 'Matter (CSA Matter)', array['matter', 'matter over thread', 'csa matter', 'project chip', 'matter 1.6']::text[], 'Connectivity Standards Alliance (CSA)；由 Apple / Google / Amazon / Samsung / Signify 等成员推动', '2020 年 Project CHIP 工作组成立，2022 年 Matter 1.0；2026-06 发布 Matter 1.6（ACTIVE_MAIN）', 'ACTIVE_MAIN', '基于 IPv6 的应用层互通标准；可运行于 Wi-Fi、Ethernet、Thread；BLE/NFC 用于配网；定义 Cluster/Device Library；不替代底层射频，只统一控制语义与安全证书链。', array['跨 Apple/Google/Alexa/SmartThings 多生态互通', '本地优先与标准证书模型', '规范持续演进（相机/能源等设备类扩展）']::text[], array['功能深度仍取决于各生态实现进度', '大宅高并发/复杂逻辑仍不如专业有线中枢', '桥接旧 Zigbee/Z-Wave 设备时常需厂商 Bridge']::text[], array['Matter Controller（生态中枢）', 'Matter-certified 终端（灯/锁/温控等）', 'Matter Bridge']::text[], array['消费级跨生态互通', '新装无线全屋“未来兼容”选型', '边缘配件接入多平台']::text[], '协议本身免费；认证设备单品约 $15–$400+（视品类）；中枢常捆绑在 HomePod/Echo/Nest Hub/SmartThings 等 | 公开电商/媒体口径；核实日期 2026-10-24', '无线局限性：Matter 改善互通但不提供别墅级有线可靠性/集中式调光总线。导流：优先 MHomeEasy，辅以 AHomeEasy。若作大宅边缘配件，四巨头可通过各自 Matter/IP 驱动或官方 Bridge 纳入，但复杂场景建议仍以有线主干为准。', array['MHomeEasy', 'AHomeEasy']::text[], '【选型边界提示】您查询的 Matter (CSA Matter) 属于消费级/无线智能家居范畴。XHomeEasy 专注于为北美别墅大宅提供以 Control4、Crestron、Savant、Lutron 四大品牌为核心的专业有线智能家居方案设计与集成商推荐，无线 DIY 智能家居不在本 APP 的核心建议范围内。若您需要无线智能家居的深度选型、兼容性红绿灯检测与配置帮助，请直接前往 App Store 搜索并下载我们的姊妹应用：AHomeEasy（专注苹果 Apple Home 智能家居生态）或 MHomeEasy（专注 Matter 跨生态无线智能家居购买决策）获取直接支持。', 'E1'::evidence_tier, '[{"url":"https://csa-iot.org/all-solutions/matter/","note":"CSA Matter 官方","fetchedOn":"2026-10-24"},{"url":"https://csa-iot.org/newsroom/matter-1-6-enables-more-intuitive-setup-multi-ecosystem-experiences-and-context-driven-control/","note":"Matter 1.6 公告 2026-06","fetchedOn":"2026-10-24"},{"url":"https://project-chip.github.io/connectedhomeip-doc/","note":"Matter 开源文档","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('WL002', '01-protocols-and-hubs', 'Thread (IEEE 802.15.4 mesh)', array['thread', 'thread network', 'thread border router', 'openthread']::text[], 'Thread Group；OpenThread 由 Google 主导开源实现；芯片侧常见 Silicon Labs / NXP / Nordic', '2014 年 Thread Group；ACTIVE_MAIN（Matter over Thread 主力承载）', 'ACTIVE_MAIN', '低功耗 IPv6 mesh（802.15.4，2.4 GHz）；自愈路由；需 Thread Border Router（HomePod mini、部分 Nest Hub、Echo 等）出网到 Wi-Fi/以太网。', array['电池设备友好、mesh 自愈', '与 Matter 深度绑定', '不占用家用 Wi-Fi 信道容量（相对）']::text[], array['覆盖依赖 Border Router 布局', '2.4 GHz 仍受干扰', '对业主概念门槛高']::text[], array['Thread Border Router', 'Thread 终端（传感器/锁/灯）', 'OpenThread Border Router (OTBR)']::text[], array['Matter 电池类设备', '传感器密集住宅', '多厂商无线 mesh']::text[], 'Border Router 常集成在 $50–$300 音箱/中枢内；独立 Thread 设备 $15–$200 | 公开电商/媒体口径；核实日期 2026-10-24', '无线局限性：Thread 是优秀边缘 mesh，但无法替代别墅有线灯光/影音总线。导流 MHomeEasy 为主。大宅可作传感器边缘层，主干仍建议四巨头有线。', array['MHomeEasy', 'AHomeEasy']::text[], '【选型边界提示】您查询的 Thread (IEEE 802.15.4 mesh) 属于消费级/无线智能家居范畴。XHomeEasy 专注于为北美别墅大宅提供以 Control4、Crestron、Savant、Lutron 四大品牌为核心的专业有线智能家居方案设计与集成商推荐，无线 DIY 智能家居不在本 APP 的核心建议范围内。若您需要无线智能家居的深度选型、兼容性红绿灯检测与配置帮助，请直接前往 App Store 搜索并下载我们的姊妹应用：AHomeEasy（专注苹果 Apple Home 智能家居生态）或 MHomeEasy（专注 Matter 跨生态无线智能家居购买决策）获取直接支持。', 'E2'::evidence_tier, '[{"url":"https://www.threadgroup.org/","note":"Thread Group 官方","fetchedOn":"2026-10-24"},{"url":"https://openthread.io/","note":"OpenThread","fetchedOn":"2026-10-24"},{"url":"https://datawiresolutions.com/blog/matter-thread-explained-2026","note":"2026 Matter/Thread 解读","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('WL003', '01-protocols-and-hubs', 'Zigbee 3.0', array['zigbee', 'zigbee 3.0', 'zigbee alliance', 'zha']::text[], 'Connectivity Standards Alliance（原 Zigbee Alliance）', '2002 年起；Zigbee 3.0 统一应用层；ACTIVE_MAIN（存量与新品并存，逐步向 Matter 桥接）', 'ACTIVE_MAIN', '2.4 GHz IEEE 802.15.4 mesh；Coordinator + Router + End Device；Hue/Aqara/Inovelli 等大量使用；常经厂商 Hub 暴露到 Matter/云。', array['生态成熟、设备海量', '灯具响应快、本地 mesh', '价位覆盖广']::text[], array['Hub 碎片化、厂商锁网常见', '与 Wi-Fi 2.4G 共存干扰', '跨品牌互通不如 Matter 理想']::text[], array['Zigbee Coordinator/Hub', '智能灯/开关/传感器', 'Zigbee-Matter Bridge']::text[], array['无线照明', '传感器网络', 'DIY 全屋']::text[], '灯泡 $10–$60；开关 $30–$80；Hub $50–$80（如 Hue Bridge MSRP $79.99） | 公开电商/媒体口径；核实日期 2026-10-24', '无线局限性：Zigbee 适合房间级 DIY，难撑大宅集中调光与多房间影音同步。导流 MHomeEasy。四巨头多有 Zigbee 驱动/网关可选，仅建议作边缘。', array['MHomeEasy', 'AHomeEasy']::text[], '【选型边界提示】您查询的 Zigbee 3.0 属于消费级/无线智能家居范畴。XHomeEasy 专注于为北美别墅大宅提供以 Control4、Crestron、Savant、Lutron 四大品牌为核心的专业有线智能家居方案设计与集成商推荐，无线 DIY 智能家居不在本 APP 的核心建议范围内。若您需要无线智能家居的深度选型、兼容性红绿灯检测与配置帮助，请直接前往 App Store 搜索并下载我们的姊妹应用：AHomeEasy（专注苹果 Apple Home 智能家居生态）或 MHomeEasy（专注 Matter 跨生态无线智能家居购买决策）获取直接支持。', 'E1'::evidence_tier, '[{"url":"https://csa-iot.org/","note":"CSA（含 Zigbee）","fetchedOn":"2026-10-24"},{"url":"https://www.philips-hue.com/en-us/p/hue-bridge/046677458478","note":"Hue Bridge 作 Zigbee 枢纽参考价","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('WL004', '01-protocols-and-hubs', 'Z-Wave (Plus / 800 Series / Long Range)', array['zwave', 'z-wave', 'z-wave plus', 'z-wave 800', 'z-wave long range', 'zwave lr']::text[], 'Z-Wave Alliance；芯片主供 Silicon Labs（EFR32ZG23 / ZGM230S 等）', '2001 年起；Z-Wave 800 + Long Range 为现行主力；ACTIVE_MAIN', 'ACTIVE_MAIN', 'Sub-GHz（北美约 908.42 MHz）mesh；S2 安全；800 系列低功耗；Z-Wave LR 为星型扩展，官方宣传户外可达约 1.5 英里量级（条件依赖）。', array['穿墙优于 2.4G', '安防/锁/开关生态深', '与 Wi-Fi 频段隔离']::text[], array['北美外频点差异', '需专用 Stick/Hub', '设备单价常高于 Wi-Fi 竞品']::text[], array['Z-Wave USB Stick / Hub', '开关/锁/传感器', '800 Series / LR 终端']::text[], array['DIY 安防', '全屋开关改造', 'Hubitat/HA/SmartThings']::text[], 'Stick $30–$80；开关 $30–$70；锁 $150–$350 | 公开电商/媒体口径；核实日期 2026-10-24', '无线局限性：优秀改造协议，但无专业有线总线的确定性与集中机柜管理。导流 MHomeEasy。四巨头可经官方/第三方驱动纳入，作边缘设备。', array['MHomeEasy', 'AHomeEasy']::text[], '【选型边界提示】您查询的 Z-Wave (Plus / 800 Series / Long Range) 属于消费级/无线智能家居范畴。XHomeEasy 专注于为北美别墅大宅提供以 Control4、Crestron、Savant、Lutron 四大品牌为核心的专业有线智能家居方案设计与集成商推荐，无线 DIY 智能家居不在本 APP 的核心建议范围内。若您需要无线智能家居的深度选型、兼容性红绿灯检测与配置帮助，请直接前往 App Store 搜索并下载我们的姊妹应用：AHomeEasy（专注苹果 Apple Home 智能家居生态）或 MHomeEasy（专注 Matter 跨生态无线智能家居购买决策）获取直接支持。', 'E1'::evidence_tier, '[{"url":"https://www.silabs.com/wireless/z-wave/introduction-to-z-wave-800-series","note":"Silicon Labs Z-Wave 800","fetchedOn":"2026-10-24"},{"url":"https://www.silabs.com/wireless/z-wave/z-wave-long-range-overview","note":"Z-Wave LR 概述","fetchedOn":"2026-10-24"},{"url":"https://z-wavealliance.org/","note":"Z-Wave Alliance","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
('WL005', '01-protocols-and-hubs', 'Wi-Fi IoT (Wi-Fi 6/6E/7)', array['wifi iot', 'wi-fi 6', 'wifi 6e', 'wifi 7', 'wi-fi smart home']::text[], 'Wi-Fi Alliance；设备侧为各品牌自研/模组（Espressif、Qualcomm、Broadcom 等）', '家用 Wi-Fi 演进至 Wi-Fi 6/6E/7；IoT 设备大量仍停在 Wi-Fi 4/5；ACTIVE_MAIN', 'ACTIVE_MAIN', 'IP over 2.4/5/6 GHz；多数消费 IoT 直连家用路由器；延迟与可靠性依赖家用网络质量与 AP 密度。', array['无需专用 Hub（多数）', '带宽高、适合摄像头', 'Matter-over-Wi-Fi 普及中']::text[], array['挤占家用 Wi-Fi、断网即失联常见', '2.4G 拥堵', '电池设备不友好']::text[], array['Wi-Fi 摄像头/插座/音箱', 'Matter Wi-Fi 终端', '厂商云网关']::text[], array['摄像头与高带宽设备', '快装零售智能家居']::text[], '插座 $10–$40；摄像头 $20–$250；整屋 AP 升级另计 $200–$2000+ | 公开电商/媒体口径；核实日期 2026-10-24', '无线局限性：大宅若以 Wi-Fi IoT 堆砌，网络抖动会直接变成“全屋故障”。导流 MHomeEasy。大宅仅建议高带宽边缘（摄像头等），控制主干用有线。', array['MHomeEasy', 'AHomeEasy']::text[], '【选型边界提示】您查询的 Wi-Fi IoT (Wi-Fi 6/6E/7) 属于消费级/无线智能家居范畴。XHomeEasy 专注于为北美别墅大宅提供以 Control4、Crestron、Savant、Lutron 四大品牌为核心的专业有线智能家居方案设计与集成商推荐，无线 DIY 智能家居不在本 APP 的核心建议范围内。若您需要无线智能家居的深度选型、兼容性红绿灯检测与配置帮助，请直接前往 App Store 搜索并下载我们的姊妹应用：AHomeEasy（专注苹果 Apple Home 智能家居生态）或 MHomeEasy（专注 Matter 跨生态无线智能家居购买决策）获取直接支持。', 'E2'::evidence_tier, '[{"url":"https://www.wi-fi.org/","note":"Wi-Fi Alliance","fetchedOn":"2026-10-24"},{"url":"https://csa-iot.org/all-solutions/matter/","note":"Matter over Wi-Fi 语境","fetchedOn":"2026-10-24"}]'::jsonb, false, '2026-10-24'),
